import type {
  DifficultyTier,
  EquipmentType,
  ExerciseKind,
  ExerciseType,
  InjuryArea,
  MovementCategory,
  MuscleGroup,
  TrainingCategory,
} from "@/lib/types/enums";

export type ExerciseSeed = {
  name: string;
  workoutCategory: TrainingCategory;
  movementCategory: MovementCategory;
  kind: ExerciseKind;
  /** Working-set rep range per the Workout Playbook's double progression model */
  repRangeLow?: number;
  repRangeHigh?: number;
  /** Realistic per-session weight increment once an exercise is ready to progress */
  defaultIncrementLb?: number;
  /** Equipment required to perform this exercise - filters recommendations by the user's equipment access */
  equipment: EquipmentType;
  /**
   * Anatomical mover, distinct from workoutCategory's training-day grouping
   * (an Overhead Press is chest_triceps but muscleGroup "shoulders").
   * Block periodization selects by muscle group.
   */
  muscleGroup: MuscleGroup;
  /** Multi-joint vs single-joint vs lighter accessory work - block focus filters on this */
  exerciseType: ExerciseType;
  /** Filtered against the user's experience level */
  difficultyTier: DifficultyTier;
  /**
   * Joints this lift meaningfully loads. Users who flag one of these areas as
   * injured never get the exercise recommended.
   */
  contraindications: InjuryArea[];
};

